// Normalização do payload de entrada da Evolution API ou Z-API
const body = $input.first().json.body || $input.first().json;

const remoteJid = body.data?.key?.remoteJid || body.sender || body.from || '5511999999999@s.whatsapp.net';
const messageType = body.data?.messageType || body.messageType || (body.data?.message?.audioMessage ? 'audioMessage' : 'conversation');
const textMessage = body.data?.message?.conversation || body.data?.message?.extendedTextMessage?.text || body.text || '';
const audioUrl = body.data?.message?.audioMessage?.url || body.audioUrl || null;
const base64Audio = body.data?.message?.base64 || body.base64 || null;

return {
  remoteJid,
  messageType,
  textMessage: textMessage.trim(),
  audioUrl,
  base64Audio,
  isAudio: messageType === 'audioMessage' || !!audioUrl || !!base64Audio
};

// Unifica o texto seja ele vindo de áudio (transcrito) ou direto em texto
const inputData = $('Normalizar Mensagem Recebida').first().json;
const transcription = $json.text || inputData.textMessage || '';

return {
  remoteJid: inputData.remoteJid,
  rawInput: transcription,
  originalWasAudio: inputData.isAudio
};

const extracted = $json.message?.content ? JSON.parse($json.message.content) : $json;
const user = $('Consolidar Texto Recebido').first().json;

// Decisão de fluxo com base no estado e na intenção
const intencao = (extracted.intencao_confirmacao || '').toUpperCase();

if (intencao.includes('SIM') || intencao.includes('CORRETO') || intencao.includes('CONFIRMO')) {
  return {
    status: 'CONFIRMADO',
    protocolo: 'DIX-' + Math.floor(100000 + Math.random() * 900000),
    nome: extracted.nome || 'Cliente',
    mensagem: `✅ Perfeito! Seu chamado foi aberto com sucesso.\n\n📋 *Protocolo:* DIX-${Math.floor(100000 + Math.random() * 900000)}\n👤 *Nome:* ${extracted.nome}\n📧 *E-mail:* ${extracted.email}\n📱 *Telefone:* ${extracted.telefone}\n📝 *Ocorrência:* ${extracted.descricao_problema}\n\nUm de nossos analistas do suporte humanizado entrará em contato em instantes. Por favor, aguarde!`
  };
} else if (intencao.includes('NÃO') || intencao.includes('NAO') || intencao.includes('ERRADO')) {
  return {
    status: 'RECUSADO',
    mensagem: `⚠️ Sem problemas! Vamos corrigir seus dados.\n\nPor favor, envie novamente (por texto ou áudio) seu *Nome completo*, *E-mail*, *Celular* e o detalhe da sua ocorrência:`
  };
} else {
  return {
    status: 'VALIDACAO',
    mensagem: `👋 Olá! Recebemos seus dados.\n\nPor favor, *confirme se as informações abaixo estão corretas*:\n\n👤 *Nome:* ${extracted.nome || 'Não identificado'}\n📧 *E-mail:* ${extracted.email || 'Não identificado'}\n📱 *Celular:* ${extracted.telefone || user.remoteJid.replace('@s.whatsapp.net', '')}\n📝 *Ocorrência:* ${extracted.descricao_problema || 'Suporte técnico'}\n\n👉 Responda com *SIM* para confirmar e abrir o chamado, ou *NÃO* para reenviar os dados.`
  };
}
